def solve_distribution(n):
    N = 2 * n + 1
    counts = {k: 0 for k in range(N)}

    for j in range(1, N + 1):
        # P_j = j(j+1)/2 - 1 mod N
        P_j = (j * (j + 1) // 2 - 1) % N
        counts[P_j] += 1

    # Format the results
    result = {k: v for k, v in counts.items()}
    return result

results = {}
for n in range(1, 11):
    results[n] = solve_distribution(n)

for n, counts in results.items():
    print(f"N={2*n+1} (n={n}): {counts}")
